SELECT AVG(icustays.los) AS average_los FROM admissions JOIN patients ON admissions.subject_id = patients.subject_id JOIN icustays ON admissions.stay_id = icustays.stay_id WHERE patients.gender = 'F' AND patients.anchor_age = 88 AND EXTRACT(YEAR FROM admissions.admittime) BETWEEN 2015 AND 2016 AND admissions.admission_type = 'C' AND admissions.hadm_id IN (SELECT diagnoses_icd.hadm_id FROM diagnoses_icd WHERE diagnoses_icd.icd_code = '840580') AND icustays.los IS NOT NULL;